namespace ID_Indetails.api.Models;

/// <summary>
/// Time an employee logged against a Design project. Soft-deleted only, because the
/// project timeline reconstructs history from these rows.
/// </summary>
public class WorkEntry
{
    public long Id { get; set; }

    public long UserId { get; set; }

    public long ProjectId { get; set; }

    public string Description { get; set; } = string.Empty;

    public DateTime StartedAt { get; set; }

    public DateTime EndedAt { get; set; }

    /// <summary>Generated by MySQL from StartedAt and EndedAt; never written by the app.</summary>
    public int DurationMinutes { get; private set; }

    public long? AttachmentFileId { get; set; }

    public DateTime CreatedAt { get; set; }

    public DateTime? UpdatedAt { get; set; }

    public DateTime? DeletedAt { get; set; }

    public User User { get; set; } = null!;

    public Project Project { get; set; } = null!;

    public StoredFile? AttachmentFile { get; set; }

    public ICollection<WorkEntryComment> Comments { get; set; } = new List<WorkEntryComment>();
}
